<script setup>
import {computed,onMounted,onUnmounted,ref,watch,nextTick} from 'vue'
import {requestJson,postAction} from '../api.js'
import OperationsConsole from './OperationsConsole.vue'
import TrafficScene from './CityTrafficMap.vue'
import {atTime,flightState,profile,effectiveFlights,reasonNames,actionNames,modeNames} from '../traffic/runtime.js'
const activeSection=ref('overview'),settings=ref(false),operations=ref([]),operationsReady=ref(false),commandBusy=ref(false),mapExpanded=ref(false)
const workbench=ref(null)
const sections={overview:'运行总览',schedule:'调度台账',alerts:'预警中心',weather:'气象监测',assistant:'智能研判',history:'操作记录'}
const network=ref(null),session=ref(null),weather=ref(null),error=ref(''),busy=ref(false)
const seed=ref(42),scenario=ref('moving'),city=ref(''),minute=ref(60),playing=ref(false),speed=ref(1)
const showCar=ref(true),showDelivery=ref(true),showWeather=ref(true),showWind=ref(true),search=ref(''),status=ref('ALL'),page=ref(1),selectedId=ref(''),scene=ref(null)
let generation=0,weatherGeneration=0,poll=null,timer=null,disposed=false
const stateNames={AIRBORNE:'飞行中',HOLD:'等待放行',PENDING:'待执行',ARRIVED:'已到达',CLOSED:'已关闭'}
const provinces=['辽宁省','吉林省','黑龙江省']
const appliedOperationKey=computed(()=>operations.value.flatMap((op,i)=>op.minute<=minute.value?[i]:[]).join(','))
const flights=computed(()=>session.value?.status==='READY'&&operationsReady.value?effectiveFlights(session.value.flights,appliedOperationKey.value?appliedOperationKey.value.split(',').map(i=>operations.value[Number(i)]):[],Infinity):[])
const filtered=computed(()=>flights.value.filter(f=>(f.mode==='CAR'?showCar.value:showDelivery.value)&&(!city.value||[f.fromCity,f.toCity].includes(city.value))&&(!search.value||f.name.includes(search.value)||f.id.toLowerCase().includes(search.value.toLowerCase()))&&(status.value==='ALL'||flightState(f,minute.value)===status.value)))
const rows=computed(()=>filtered.value.slice((page.value-1)*20,page.value*20))
const selected=computed(()=>flights.value.find(f=>f.id===selectedId.value))
const scoped=computed(()=>flights.value.filter(f=>(f.mode==='CAR'?showCar.value:showDelivery.value)&&(!city.value||[f.fromCity,f.toCity].includes(city.value))))
const counts=computed(()=>{const c={AIRBORNE:0,HOLD:0,PENDING:0,ARRIVED:0,CLOSED:0};for(const f of scoped.value)c[flightState(f,minute.value)]++;return c})
const cityName=computed(()=>network.value?.cities.find(c=>c.id===city.value)?.name||'东北三省')
const location=computed(()=>selected.value?.points.length?atTime(selected.value.points,minute.value):null)
const ready=computed(()=>session.value?.status==='READY'&&operationsReady.value)
function locateDelivery(){
  const candidates=flights.value.filter(f=>f.fromCity===city.value&&f.mode==='DELIVERY'&&f.points.length)
  const f=candidates.find(f=>f.separationAction==='CROSSING_RAMP')||candidates[0]
  if(f){selectedId.value=f.id;minute.value=(f.departureMinute+f.arrivalMinute)/2;playing.value=false}
}
const selectedState=computed(()=>selected.value?flightState(selected.value,minute.value):'')
const sessionLabel=computed(()=>({clear:'晴好运行',moving:'移动气象',unknown:'气象中断'})[session.value?.scenario]||'准备模拟')
function chooseCity(id){city.value=id||'';selectedId.value='';page.value=1}
function chooseFlight(f){selectedId.value=f.id;activeSection.value='overview';if(f.mode==='DELIVERY')city.value=f.fromCity}
async function loadOperations(){
  const id=session.value?.sessionId;if(!id)return
  const data=await requestJson('/api/traffic/operations?sessionId='+id)
  if(session.value?.sessionId===id){operations.value=data;operationsReady.value=true}
}
async function commandFlight(){
  if(!selected.value||commandBusy.value||!ready.value)return
  playing.value=false;commandBusy.value=true;error.value=''
  try{await postAction('/api/traffic/command',{seed:session.value.seed,scenario:session.value.scenario,flightId:selected.value.id,minute:minute.value,action:selected.value.manuallySuspended?'RESUME':'SUSPEND'});await loadOperations()}
  catch(e){error.value=e.message}
  finally{commandBusy.value=false}
}
function clock(m){return `T+${Math.floor(m/60).toString().padStart(2,'0')}:${Math.floor(m%60).toString().padStart(2,'0')}`}
async function loadWeather(){
  if(!ready.value)return
  const token=++weatherGeneration,key=session.value.sessionId,t=minute.value
    try{const value=await requestJson(`/api/traffic/weather?seed=${session.value.seed}&scenario=${session.value.scenario}&minute=${t}${city.value?'&cityId='+encodeURIComponent(city.value):''}`);if(!disposed&&token===weatherGeneration&&key===session.value?.sessionId)weather.value=value}
  catch(e){if(token===weatherGeneration){weather.value=null;playing.value=false;error.value='气象图层读取失败，播放已暂停：'+e.message}}
}
async function generate(){
  if(busy.value)return
  const input=Number(seed.value)
  if(!Number.isInteger(input)||input<0||input>99999){error.value='种子需为 0—99999 的整数';return}
  const run=++generation;clearTimeout(poll);++weatherGeneration
  busy.value=true;playing.value=false;error.value='';session.value=null;weather.value=null;selectedId.value='';operations.value=[];operationsReady.value=false
  const params=`seed=${input}&scenario=${scenario.value}`
  async function check(){
    try{
      const data=await requestJson(`/api/traffic/session?${params}`)
      if(disposed||generation!==run)return
      session.value=data
      if(data.status==='READY'){busy.value=false;minute.value=60;page.value=1;await loadOperations();await loadWeather()}
      else if(data.status==='ERROR'){busy.value=false;error.value=data.message}
      else poll=setTimeout(check,1500)
    }catch(e){if(generation===run){busy.value=false;error.value=e.message}}
  }
  await check()
}
async function initialize(){
  try{network.value=await requestJson('/api/traffic/network');if(!disposed)await generate()}
  catch(e){error.value=e.message}
}
function download(){
  if(!ready.value)return
  const blob=new Blob([JSON.stringify({simulation:session.value,network:network.value,viewMinute:minute.value,weather:weather.value,operations:operations.value},null,2)],{type:'application/json'})
  const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`traffic-${session.value.sessionId}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)
}
watch([city,search,status,showCar,showDelivery],()=>page.value=1)
watch(activeSection,()=>{playing.value=false})
watch([activeSection,mapExpanded],async()=>{await nextTick();if(workbench.value)workbench.value.scrollTop=0})
watch(()=>Math.floor(minute.value/2),loadWeather)
watch(city,()=>{weather.value=null;loadWeather()})
watch(()=>filtered.value.length,()=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(filtered.value.length/20)))})
onMounted(()=>{initialize();timer=setInterval(()=>{if(playing.value&&ready.value){minute.value=Math.min(480,minute.value+Number(speed.value)*.2);if(minute.value===480)playing.value=false}},200)})
onUnmounted(()=>{disposed=true;++generation;++weatherGeneration;clearTimeout(poll);clearInterval(timer)})
</script>
<template>
<main ref="workbench" class="traffic-workbench" :class="{'map-expanded':mapExpanded&&activeSection==='overview'}">
  <header class="traffic-header"><div><div class="traffic-eyebrow">NORTHEAST · LOW ALTITUDE MOBILITY</div><h1>东北低空交通运行中心 <span>运行数据模拟</span></h1><p>飞行汽车城际通勤 · 无人机城区配送 · 空间与时间协同调度</p></div><div class="traffic-header-actions"><button @click="download" :disabled="!ready">导出本地记录</button><button @click="settings=!settings">运行设置</button></div></header>
  <section class="traffic-summary"><div><small>覆盖范围</small><strong>{{network?.cities.length||'—'}} <em>地级行政区</em></strong><span>辽宁 14 · 吉林 9 · 黑龙江 13</span></div><div><small>飞行汽车 / 城区配送走廊</small><strong>{{session?.stats?.carRoutes??'—'}} <em>/</em> {{session?.stats?.deliveryRoutes??'—'}}</strong><span>跨省仅省会 · {{session?.stats?.interprovincialRoutes??2}} 条跨省通道</span></div><div><small>{{cityName}} · 当前飞行中</small><strong class="cyan">{{counts.AIRBORNE}} <em>架次</em></strong><span>{{counts.HOLD}} 等待放行 · {{counts.ARRIVED}} 已到达</span></div><div><small>本轮计划关闭 / 已绕行</small><strong>{{session?.stats?.closed??'—'}} <em>/</em> {{session?.stats?.detours??'—'}}</strong><span>额外耗时超过 60 分钟不放行</span></div><div><small>本轮冲突处理</small><strong>{{session?.stats?.resolved??'—'}} <em>班次</em></strong><span>水平 250 m · 垂直 60 m 模拟间隔</span></div></section>
  <section class="traffic-toolbar" v-show="settings"><label>运行情景 <select v-model="scenario" :disabled="busy"><option value="moving">流动气象 / 城际绕行</option><option value="clear">晴好 / 交通交汇</option><option value="unknown">气象中断 / 暂停放行</option></select></label><label>随机种子 <input aria-label="模拟随机种子" type="number" min="0" max="99999" v-model="seed" :disabled="busy"></label><button class="primary" @click="generate" :disabled="busy||!network">{{busy?`正在调度 ${session?.progress||0}%`:'重新调度'}}</button><span class="traffic-session">{{sessionLabel}} · {{ready?'种子 '+session.seed:'等待计算'}} · 所有业务数据为模拟</span></section>
  <div class="traffic-error" v-if="error" role="alert">{{error}} <button @click="network?generate():initialize()" :disabled="busy">重试</button></div>
  <nav class="operations-nav"><button v-for="(name,key) in sections" :key="key" :class="{active:activeSection===key}" @click="activeSection=key">{{name}}</button><select aria-label="运行城市" v-model="city" @change="selectedId='';page=1"><option value="">东北三省 · 全域</option><optgroup v-for="p in provinces" :label="p" :key="p"><option v-for="c in network?.cities.filter(c=>c.province===p)||[]" :key="c.id" :value="c.id">{{c.name}}</option></optgroup></select></nav>
  <section class="traffic-main" v-show="activeSection==='overview'">
    <aside class="traffic-cities"><div class="traffic-panel-title">运行区域 <button @click="chooseCity('')">全域</button></div><div class="city-list"><section v-for="p in provinces" :key="p"><h3>{{p}}</h3><button v-for="c in network?.cities.filter(c=>c.province===p)||[]" :key="c.id" :class="{chosen:city===c.id}" @click="chooseCity(c.id)"><span>{{c.name}}</span><small>{{c.capital?'省会':'城区 + 城际'}}</small></button></section></div><p class="city-footnote">延边州、大兴安岭地区按地级行政区纳入。城市节点为近似位置。</p></aside>
    <div class="traffic-map-panel"><div class="traffic-map-heading"><div><h2>{{cityName}} <small>{{city?'城区空间视图':'三维运行全景'}}</small></h2><span>{{clock(minute)}} · {{city?'配送起降点与立体交汇':'点击左侧城市查看城区外卖网络'}}</span></div><div><button v-if="city" @click="locateDelivery" :disabled="!ready">定位配送航班</button> <button @click="scene?.reset()">复位视角</button> <button @click="mapExpanded=!mapExpanded">{{mapExpanded?'退出专注':'地图专注'}}</button></div></div><div class="traffic-layer-toggles"><label><input type="checkbox" v-model="showCar"><i class="car-dot"></i>飞行汽车</label><label><input type="checkbox" v-model="showDelivery"><i class="delivery-dot"></i>外卖无人机</label><label><input type="checkbox" v-model="showWeather">气象与风险</label><label><input type="checkbox" v-model="showWind">背景风向</label></div><TrafficScene v-if="network" ref="scene" :network="network" :flights="flights" :minute="minute" :city="city" :selected="selected" :weather="weather" :show-car="showCar" :show-delivery="showDelivery" :show-weather="showWeather" :show-wind="showWind" @select-city="chooseCity" @select-flight="chooseFlight"/><div class="traffic-legend"><span>蓝 / 紫：气象场</span><span class="amber">橙：谨慎飞行区</span><span class="pink">红：禁飞柱体</span><span>暗线：规划走廊 · 亮线：执行轨迹</span></div></div>
    <aside class="traffic-detail"><div class="traffic-panel-title">班次与空间剖面</div><template v-if="selected"><div class="traffic-flight-title"><small>{{modeNames[selected.mode]}} · {{stateNames[selectedState]}}</small><h2>{{selected.name}}</h2><code>{{selected.id}}</code></div><div class="detail-grid"><div><small>计划起飞</small><b>{{clock(selected.scheduledMinute)}}</b></div><div><small>实际放行</small><b>{{selected.points.length?clock(selected.departureMinute):'未放行'}}</b></div><div><small>预计到达</small><b>{{selected.points.length?clock(selected.arrivalMinute):'—'}}</b></div><div><small>延迟 / 绕行增时</small><b>{{selected.delayMinutes}} / {{selected.detourMinutes}} 分</b></div><div><small>航程</small><b>{{selected.distanceKm??'—'}} km</b></div><div><small>当前高度</small><b>{{selectedState==='AIRBORNE'?Math.round(location?.[2]||0):0}} m</b></div></div><div class="traffic-profile"><span>高度 / 飞行时间剖面</span><svg viewBox="0 0 300 110" role="img" aria-label="飞行高度剖面"><path d="M10 10V90H290" stroke="#35516b" fill="none"/><polyline :points="profile(selected.points)" fill="none" stroke="#59dffc" stroke-width="2"/><text x="12" y="105" fill="#86a6bd" font-size="9">起点 / 地面</text><text x="228" y="105" fill="#86a6bd" font-size="9">终点 / 地面</text></svg><small>最高 {{selected.maxAltitudeM??'—'}} m · 升降速率上限 3 m/s</small></div><div class="traffic-reason"><h3>{{actionNames[selected.separationAction]}}</h3><p>{{reasonNames[selected.reason]}}</p><p v-if="selected.conflictWith.length">处理过 {{selected.conflictWith.length}} 个关联冲突（最多展示 8 个）。</p><details v-if="selected.conflictWith.length"><summary>查看关联班次</summary><div v-for="id in selected.conflictWith" :key="id"><code>{{id}}</code></div></details></div><button v-if="selected.points.length" @click="minute=selected.departureMinute;playing=false">跳到该班次起飞</button><button v-if="selected.departureMinute!=null&&minute<selected.departureMinute" :disabled="commandBusy||!ready" @click="commandFlight">{{commandBusy?'操作中…':selected.manuallySuspended?'恢复原放行时隙':'暂停此班次'}}</button><button @click="activeSection='assistant'">研判此班次</button></template><template v-else><div class="traffic-empty"><span>↗</span><h3>选择一个班次</h3><p>在“调度台账”选择班次，查看起降端点、升降剖面，执行未起飞班次的暂停或恢复。</p></div><div class="traffic-rules"><h3>当前运行规则</h3><p>飞行汽车：省内邻城相连；跨省仅沈阳—长春—哈尔滨。</p><p>无人机外卖：每城 3 条合成配送走廊，业务限定城区。</p><p>对向航线分侧、分高度；交汇区升降，仍冲突则错时。</p><p>移动气象按整个飞行与等待时段保守评估，无法绕行则关闭。</p></div></template><p class="traffic-disclaimer">城市底图已接入真实道路与建筑数据。运行与气象采用模拟数据；底图建筑尚不作为实机避障或通航许可依据。</p></aside>
  </section>
  <section class="traffic-playback"><button class="primary" :disabled="!ready||session?.scenario==='unknown'" @click="playing=!playing">{{playing?'Ⅱ 暂停':'▶ 推演'}}</button><strong>{{clock(minute)}}</strong><input aria-label="运行推演时间" type="range" min="0" max="480" step="0.1" v-model.number="minute" :disabled="!ready"><span>T+08:00</span><select aria-label="推演速度" v-model.number="speed"><option :value=".25">15 倍速</option><option :value="1">60 倍速</option><option :value="5">300 倍速</option></select><span class="playback-note">前 3 小时发班 · 后续观察至 8 小时</span></section>
  <OperationsConsole v-if="!['overview','schedule'].includes(activeSection)" :view="activeSection" :session="session" :flights="scoped" :weather="weather" :selected="selected" :minute="minute" :city-name="cityName" :operations="operations" @select-flight="chooseFlight"/>
  <section class="traffic-table-panel" v-show="activeSection==='schedule'"><div class="traffic-table-heading"><div><h2>{{cityName}}运行班次 <small>{{filtered.length}} 条</small></h2><p>状态随推演时间变化；关闭记录属于本轮预先评估结果</p></div><div><input aria-label="搜索城市或班次" placeholder="搜索城市 / 班次编号" v-model="search"><select aria-label="筛选运行状态" v-model="status"><option value="ALL">全部状态</option><option v-for="(name,key) in stateNames" :value="key" :key="key">{{name}}</option></select></div></div><div class="traffic-table-scroll"><table><thead><tr><th>类型 / 班次</th><th>连接城市 / 城区线路</th><th>运行状态</th><th>计划 → 放行 → 到达</th><th>调度处理</th><th>气象研判</th></tr></thead><tbody><tr v-for="f in rows" :key="f.id" :class="{selected:f.id===selectedId}" @click="chooseFlight(f)"><td><button class="flight-link" @click.stop="chooseFlight(f)"><span :class="f.mode==='CAR'?'cyan':'amber'">{{modeNames[f.mode]}}</span><small>{{f.id}}</small></button></td><td>{{f.name}}<small>{{f.direction?'返向':'正向'}} · {{f.payload}}{{f.mode==='CAR'?'位模拟乘客':'份模拟订单'}}</small></td><td><span class="flight-state" :class="flightState(f,minute)">{{stateNames[flightState(f,minute)]}}</span></td><td>{{clock(f.scheduledMinute)}} → {{f.points.length?clock(f.departureMinute):'—'}} → {{f.points.length?clock(f.arrivalMinute):'—'}}</td><td>{{actionNames[f.separationAction]}}</td><td>{{reasonNames[f.reason]}}</td></tr><tr v-if="!rows.length"><td colspan="6" class="traffic-no-results">{{busy?'正在生成并复核运行计划…':'当前筛选无班次'}}</td></tr></tbody></table></div><div class="traffic-pagination"><span>每页 20 条 · 模拟数据可用同一种子复现</span><button @click="page--" :disabled="page<=1">上一页</button><b>{{page}} / {{Math.max(1,Math.ceil(filtered.length/20))}}</b><button @click="page++" :disabled="page*20>=filtered.length">下一页</button></div></section>
</main>
</template>
<style scoped>
.operations-nav{display:flex;align-items:center;gap:6px;padding:8px;background:#0e2131;border:1px solid #294354;border-radius:9px;margin:12px 0}.operations-nav button{border:0!important;background:transparent!important;padding:10px 15px!important;font-size:13px!important}.operations-nav button.active{background:#24566e!important;color:#c6f4ff!important}.operations-nav select{margin-left:auto;max-width:210px}.traffic-workbench .traffic-header{margin-bottom:12px}.traffic-workbench .traffic-summary>div{padding:10px 18px}.traffic-workbench .traffic-summary strong{font-size:24px;line-height:1.6}.traffic-workbench .traffic-main{grid-template-columns:165px minmax(0,1fr) 280px}.traffic-workbench .traffic-table-scroll{max-height:calc(100vh - 390px);min-height:300px}.traffic-workbench .traffic-map-heading{padding:12px 14px}.traffic-workbench .city-list{height:490px}.traffic-workbench .traffic-header h1{font-size:23px}@media(max-width:1000px){.operations-nav{flex-wrap:wrap}.operations-nav select{margin-left:0}.traffic-workbench .traffic-main{grid-template-columns:145px minmax(0,1fr)}}@media(max-width:700px){.traffic-workbench .traffic-main{grid-template-columns:1fr}.operations-nav button{font-size:11px!important;padding:8px!important}.traffic-workbench .city-list{height:130px}}
.traffic-workbench{height:100%;overflow:auto;padding:22px 26px 30px;background:radial-gradient(ellipse at 50% -10%,#17314b 0,transparent 45%),#080f19;color:#d6e5ef;font-size:13px}
.traffic-workbench button,.traffic-workbench select,.traffic-workbench input:not([type=checkbox]):not([type=range]){background:#122334;color:#bcd3e2;border:1px solid #294153;border-radius:6px;padding:8px 11px;font:inherit}.traffic-workbench button{cursor:pointer}.traffic-workbench button:hover{border-color:#65cce5;color:white}.traffic-workbench button:disabled{opacity:.45;cursor:default}.traffic-workbench button.primary{background:#246279;color:#effcff;border-color:#398098}.traffic-workbench input[type=checkbox]{accent-color:#59dffc}.traffic-workbench input[type=range]{accent-color:#59dffc;min-width:100px}
.traffic-header{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:20px}.traffic-eyebrow{font-size:10px;letter-spacing:3px;color:#688a9e;margin-bottom:8px}.traffic-header h1{font-size:25px;letter-spacing:1px}.traffic-header h1 span{font-size:11px;vertical-align:middle;padding:4px 8px;color:#f7ce89;border:1px solid #675636;border-radius:4px;margin-left:14px;letter-spacing:0}.traffic-header p{color:#7895a8;margin-top:8px;font-size:12px}.traffic-header-actions{display:flex;gap:8px}
.traffic-summary{display:grid;grid-template-columns:repeat(5,1fr);border:1px solid #263949;border-radius:10px;background:#101e2c;margin-bottom:16px}.traffic-summary>div{padding:16px 20px;border-right:1px solid #263949;min-width:0}.traffic-summary>div:last-child{border:0}.traffic-summary small{color:#8ea7b8;font-size:11px}.traffic-summary strong{display:block;font-size:27px;font-weight:500;line-height:1.8}.traffic-summary strong em{font-style:normal;font-size:12px;color:#809bac}.traffic-summary span{color:#6d899d;font-size:11px}.cyan{color:#64ddf6}.amber{color:#e8bd72}.pink{color:#ec8b9b}
.traffic-toolbar{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:15px;color:#89a3b4}.traffic-toolbar label{display:flex;align-items:center;gap:8px;font-size:12px}.traffic-toolbar input{width:100px}.traffic-session{margin-left:auto;font-size:11px}.traffic-error{background:#4d2432;border:1px solid #945063;color:#ffd3db;padding:12px;margin-bottom:12px;border-radius:8px;display:flex;justify-content:space-between;align-items:center}
